def nome_rastro(codigo, identificador):
    ordem = ('DESLIGADO', 'FOGO', 'GELO', 'ESTRELAS', 'ENERGIA')
    lista = NOMES_RASTRO.get(codigo)
    return lista[ordem.index(identificador)] if lista and identificador in ordem else identificador

IDIOMAS = tuple(NOMES)

def registrar_todos(catalogos_base):
    for codigo, catalogo in CATALOGOS_NOVOS.items():
        registrar_catalogo(codigo, catalogo, catalogos_base)

def proximo_idioma(codigo):
    idioma = normalizar_idioma(codigo)
    indice = IDIOMAS.index(idioma) if idioma in IDIOMAS else 0
    return IDIOMAS[(indice + 1) % len(IDIOMAS)]

def nome_idioma(codigo):
    return NOMES.get(normalizar_idioma(codigo), NOMES['pt_BR'])

