def rotulo_palavra(idioma):
    if idioma == 'en_US':
        return 'WORD'
    if idioma == 'pt_BR':
        return 'PALAVRA'
    return ROTULOS_HUD.get(idioma, ROTULOS_HUD['pt_PT'])[5]

# v3.248.0: cache LRU estritamente limitado para rótulos repetidos no HUD e menus.
# Chave inclui idioma: alternar idioma preserva a escolha correta, sem invalidar saves.
@lru_cache(maxsize=256)
def localizar_literal(texto, idioma):
    # Localiza também HUD compacto vindo dos módulos legados, sem alterá-los.
    if idioma not in EXTRAS:
        return texto
    condicional = _condicional_localizar(texto, idioma)
    if condicional != texto:
        return condicional
    texto_secundario = _secundarios_localizar(texto, idioma)
    if texto_secundario != texto:
        return texto_secundario
    traducoes = EXTRAS[idioma]
    if texto in traducoes:
        return traducoes[texto]
    curto = ROTULOS_HUD[idioma]
    if texto in ('DISTANCE','DISTÂNCIA'):
        return curto[0]
    for prefixos,indice in ((('MISSIONS  ','MISSÕES  '),1),(('FEVER  ','FEBRE  '),2),
                            (('ACTIVE','ATIVOS'),3),(('BOOST','IMPULSO'),4)):
        for prefixo in prefixos:
            if texto.startswith(prefixo):
                return curto[indice]+texto[len(prefixo):]
    return texto

@lru_cache(maxsize=24)
def fonte_unicode(codigo, tamanho):
    import pygame
    caminho = ARQUIVOS_FONTES.get(codigo)
    if caminho is None:
        return None
    return pygame.font.Font(str(Path(__file__).resolve().parent / caminho), tamanho)
